NativeCalloutDispatch Dispatch_vfs_AbortDownload(NativeInterface* nativeInterface, const std::vector<WasmValue>& arguments, WasmValue& result, std::string& error)
{
	if (nativeInterface == nullptr || nativeInterface->vfs == nullptr || nativeInterface->vfs->AbortDownload == nullptr) { error = "NativeInterface API is unavailable: vfs.AbortDownload"; return NativeCalloutDispatch::handled; }
	NativeCallStorage storage;
	AbortDownloadQuery query{};
	AbortDownloadResult nativeResult{};
	if (!ReadArgument(arguments, 0u, 0u, 1u, 1u, "id", query.id, error)) return NativeCalloutDispatch::handled;
	nativeInterface->vfs->AbortDownload(&query, &nativeResult);
	if (!CheckNativeError(nativeResult, error)) return NativeCalloutDispatch::handled;
	result = WriteScalar(nativeResult.removed);
	return NativeCalloutDispatch::handled;
}

